import 'package:in_app_purchase/in_app_purchase.dart';
Future<void> buy()async{
  final iap=InAppPurchase.instance;
  if(!await iap.isAvailable())throw Exception('iap unavailable');
  final r=await iap.queryProductDetails({'{{product_id}}'});
  if(r.notFoundIDs.isNotEmpty)throw Exception('product missing');
  final p=PurchaseParam(productDetails:r.productDetails.first);
  await iap.buyConsumable(purchaseParam:p);}
